class Solution:
    def checkValidString(self, s: str) -> bool:
        open_stack = []
        star_stack = []
        for i, char in enumerate(s):

            # Add open brackets to open_stack and star to star_stack
            if char == "(":
                open_stack.append(i)
            elif char == "*":
                star_stack.append(i)

            # Check the current opening brackets or star, pop them in case they match the closing bracket
            # If no matching bracket is found, then the expression is not valid.
            elif char == ")":
                if open_stack:
                    open_stack.pop()
                elif star_stack:
                    star_stack.pop()
                else:
                    return False

        # Check the length of the remaining stacks
        while open_stack and star_stack:
            o = open_stack.pop()
            s = star_stack.pop()

            if o > s:
                return False

        return len(open_stack) == 0

//program for string matching using greedy algorithm 

#include<stdio.h>
#include<stdbool.h>

// Function to find match between given string and pattern 
bool stringMatching(char string[], char pattern[]) 
{ 
	//calculate length of given string 
	int n = strlen(string);  

	//calculate length of given pattern  
	int m = strlen(pattern);  

	// indices of string and pattern 
	int i = 0, j = 0;  

	// Greedy loop to match 
	while(i < n && j < m) { 
		if(string[i] == pattern[j]) { 
			i++; 
			j++; 
		} 
		// Go back one position in string 
		else { 
			i = i - j + 1; 
			j = 0; 
		}	 
	} 

	// Check whether pattern is found or not 
	if(j == m) 
		return true; 

	return false; 
} 

// Driver code 
int main() 
{ 
	char string[] = "ababcab"; 
	char pattern[] = "cab"; 

	bool flag = stringMatching(string, pattern); 

	if (flag) 
		printf("Pattern matches"); 
	else
		printf("Pattern do not matches"); 

	return 0; 
}

// Program to implement the bubble sort algorithm 
#include <stdio.h> 

void bubbleSort(int arr[], int n) 
{ 
	int i, j; 
	for (i = 0; i < n-1; i++)	 

	// Last i elements are already in place 
	for (j = 0; j < n-i-1; j++) 
		if (arr[j] > arr[j+1]) 
			swap(&arr[j], &arr[j+1]); 
} 

void swap(int *a, int *b) 
{ 
	int temp = *a; 
	*a = *b; 
	*b = temp; 
} 

// Driver program 
int main() 
{ 
	int arr[] = {64, 34, 25, 12, 22, 11, 90}; 
	int n = sizeof(arr)/sizeof(arr[0]); 
	bubbleSort(arr, n); 
	return 0; 
}

public class MaxNumber {
    public static int findMax(int[] arr) {
        int max = Integer.MIN_VALUE;
        for (int i=0; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        return max;
    }

    public static void main(String[] args) {
        int[] numbers = {2, 3, 1, 5, 9};
        int max = findMax(numbers);
        System.out.println("The maximum number is: " + max);
