// Function to reverse the elements of an array 
void reverseArray(int arr[], int start, int end) 
{ 
    while (start < end) 
    { 
        int temp = arr[start];  
        arr[start] = arr[end]; 
        arr[end] = temp; 
        start++; 
        end--; 
    }  
} 

int main() 
{ 
    int arr[] = {1,2,3,4,5}; 

    // reverse the elements 
    reverseArray(arr, 0, 4); 

    // print the reversed array 
    for (int i=0; i<5; i++) 
        cout << arr[i] << " "; 

    return 0; 
}

